const EN8_STORIES = [
  { p: "One windy afternoon at the park, Hana's kite got stuck in a tall tree. She tugged the string, but it would not come loose. A kind park ranger brought a long pole and gently freed the kite.", c: "Hana", s: "a park on a windy afternoon", pr: "Her kite got stuck in a tree.", so: "A park ranger freed it with a long pole.", wc: ["the park ranger", "a squirrel", "her dad"], ws: ["a snowy mountain", "a school bus", "a bakery"], wp: ["She lost her shoe.", "It started to snow.", "Her dog ran away."], wo: ["She bought a new kite.", "The wind blew it down.", "She climbed the tree."] },
  { p: "In the kitchen on Sunday morning, Leo wanted to make pancakes for his family. When he opened the fridge, there were no eggs! Leo went next door, and his neighbor gave him two eggs.", c: "Leo", s: "the kitchen on Sunday morning", pr: "There were no eggs.", so: "His neighbor gave him two eggs.", wc: ["the neighbor", "a chicken", "his sister"], ws: ["a pirate ship", "a swimming pool", "a forest at night"], wp: ["The stove was broken.", "He burned the pancakes.", "He was late for school."], wo: ["He made toast instead.", "He went back to bed.", "He called a chef."] },
  { p: "At the bottom of the sea, a little crab named Clara lost her shell in a storm. She felt cold without it. Her friend Octavia the octopus helped her find a new shell inside an old sunken boat.", c: "Clara the crab", s: "the bottom of the sea", pr: "She lost her shell.", so: "Her octopus friend helped her find a new shell.", wc: ["Octavia the octopus", "a shark", "a fisherman"], ws: ["a desert", "a treehouse", "a library"], wp: ["She was too hungry.", "Her claw was hurt.", "She could not swim."], wo: ["She built a house of sand.", "She swam to the beach.", "She took a nap."] },
  { p: "During recess on a sunny day, Omar wanted to play soccer with his friends. But the ball was flat! Omar asked the gym teacher, who pumped it full of air.", c: "Omar", s: "recess on a sunny day", pr: "The soccer ball was flat.", so: "The gym teacher pumped it full of air.", wc: ["the gym teacher", "the soccer ball", "the principal"], ws: ["a rainy night", "a dentist's office", "a farm"], wp: ["It began to rain.", "Omar hurt his leg.", "Recess was canceled."], wo: ["They played tag instead.", "Omar bought a new ball.", "They all went inside."] },
  { p: "On a cold winter night, Bella the bear could not fall asleep in her cave. Her tummy kept rumbling. Her mother brought her a snack of berries, and soon Bella was snoring.", c: "Bella the bear", s: "a cave on a cold winter night", pr: "She could not fall asleep.", so: "Her mother gave her a snack of berries.", wc: ["Bella's mother", "an owl", "a rabbit"], ws: ["a sunny beach", "a city street", "a classroom"], wp: ["Her cave was flooded.", "She lost her toy.", "It was too hot."], wo: ["She went for a swim.", "She counted sheep.", "She moved to a new cave."] },
  { p: "At the county fair, Jamal entered his giant pumpkin in a contest. On the morning of the contest, his wagon got a flat tire. Jamal and his cousin rolled the pumpkin across the field together.", c: "Jamal", s: "the county fair", pr: "His wagon got a flat tire.", so: "He and his cousin rolled the pumpkin.", wc: ["his cousin", "the judge", "a farmer"], ws: ["a space station", "the ocean", "a hospital"], wp: ["His pumpkin was too small.", "He lost his ticket.", "It started to snow."], wo: ["He gave up.", "He bought a new wagon.", "He carved the pumpkin."] },
  { p: "In a quiet forest, a young owl named Ollie was afraid of the dark. All the other owls loved flying at night. Grandma Owl taught Ollie to look up at the bright stars, and soon he loved the night sky too.", c: "Ollie the owl", s: "a quiet forest", pr: "He was afraid of the dark.", so: "Grandma Owl taught him to look at the stars.", wc: ["Grandma Owl", "a fox", "a bat"], ws: ["a busy mall", "a sunny beach", "a city bus"], wp: ["He could not find food.", "His wing was hurt.", "He was too big."], wo: ["He moved to the city.", "He stayed in his nest forever.", "He turned on a lamp."] },
  { p: "On the first snowy day of winter, Mia built a snowman in her backyard. When she finished, she noticed it had no nose. Mia ran inside and came back with a carrot.", c: "Mia", s: "her backyard on a snowy day", pr: "The snowman had no nose.", so: "She used a carrot for a nose.", wc: ["the snowman", "her mom", "a bird"], ws: ["a hot desert", "a movie theater", "a beach in summer"], wp: ["The snow melted.", "She lost her mittens.", "She was too cold."], wo: ["She knocked it down.", "She drew a nose on paper.", "She gave up."] },
  { p: "At the pool on a hot day, Zoe wanted to jump off the diving board. When she reached the top, she felt nervous. Her swim coach smiled and counted to three, and Zoe jumped with a big splash.", c: "Zoe", s: "the pool on a hot day", pr: "She felt nervous at the top of the diving board.", so: "Her coach counted to three, and she jumped.", wc: ["the swim coach", "a lifeguard", "a duck"], ws: ["a snowy hill", "a library", "a movie theater"], wp: ["The pool was closed.", "She lost her goggles.", "It started to rain."], wo: ["She climbed back down.", "She went home.", "She fell asleep."] },
  { p: "In a busy city apartment, Ravi's goldfish looked bored in its small bowl. Ravi saved his allowance for a month. Then he bought a big tank with plants and a tiny castle for his fish.", c: "Ravi", s: "a busy city apartment", pr: "His goldfish looked bored in a small bowl.", so: "He saved money and bought a big tank.", wc: ["the goldfish", "a pet store worker", "his mom"], ws: ["a farm", "a jungle", "an island"], wp: ["His fish was sick.", "He lost his money.", "The bowl broke."], wo: ["He let the fish go in a lake.", "He bought a cat.", "He gave the fish away."] },
  { p: "On a class field trip to the museum, Ana got separated from her group. She remembered what her teacher said and went to the information desk. A museum worker called her teacher, and Ana was back with her class in minutes.", c: "Ana", s: "the museum on a field trip", pr: "She got separated from her group.", so: "She went to the information desk for help.", wc: ["the museum worker", "her teacher", "a dinosaur"], ws: ["a campsite", "a beach", "a grocery store"], wp: ["She forgot her lunch.", "The museum was closed.", "She broke a statue."], wo: ["She walked home alone.", "She hid behind a statue.", "She left the museum."] },
  { p: "Long ago in a small village, a baker named Pia ran out of flour on the morning of the big festival. Everyone wanted her famous bread. Her friends from the village each brought a little flour, and Pia baked enough bread for everyone.", c: "Pia the baker", s: "a small village long ago", pr: "She ran out of flour.", so: "Her friends each brought a little flour.", wc: ["the villagers", "a king", "a farmer"], ws: ["a spaceship", "a big city today", "under the sea"], wp: ["Her oven was too hot.", "She lost her apron.", "Nobody liked bread."], wo: ["She canceled the festival.", "She baked cookies instead.", "She went to sleep."] },
  { p: "In the garden behind the school, a caterpillar named Lulu wanted to see the whole garden. But she was too small to see over the tall grass. Lulu climbed to the top of a sunflower and could see everything.", c: "Lulu the caterpillar", s: "the garden behind the school", pr: "She was too small to see over the tall grass.", so: "She climbed to the top of a sunflower.", wc: ["a sunflower", "a bee", "the gardener"], ws: ["a frozen lake", "a pirate ship", "a train station"], wp: ["She was hungry.", "It was raining.", "She lost her friend."], wo: ["She asked a bird to carry her.", "She dug a tunnel.", "She went to sleep."] },
  { p: "On a rainy Saturday at home, Eli was bored. His dad gave him a big empty box. Eli turned it into a spaceship and spent the whole day exploring pretend planets.", c: "Eli", s: "home on a rainy Saturday", pr: "Eli was bored.", so: "He turned a box into a pretend spaceship.", wc: ["his dad", "an astronaut", "an alien"], ws: ["outer space", "a sunny beach", "a school gym"], wp: ["The box was broken.", "He was sick.", "The power went out."], wo: ["He watched TV all day.", "He went to the beach.", "He took a nap."] },
  { p: "At the busy airport, Grandpa Joe could not find his glasses. Without them, he could not read the signs. He searched his bag and his pockets. Then his granddaughter Lily pointed to the glasses sitting on top of his head!", c: "Grandpa Joe", s: "the busy airport", pr: "He could not find his glasses.", so: "Lily saw them on top of his head.", wc: ["a pilot", "a flight attendant", "a security guard"], ws: ["a farm", "a bakery", "a forest"], wp: ["He missed his plane.", "He lost his suitcase.", "He was hungry."], wo: ["He bought new glasses.", "He went home.", "A pilot read the signs to him."] },
  { p: "On the morning of the big race, Tess the tortoise found a fallen log blocking the path. She was too small to climb over it. Tess dug a little tunnel under the log and kept going to the finish line.", c: "Tess the tortoise", s: "a path on the morning of a big race", pr: "A fallen log blocked the path.", so: "She dug a tunnel under the log.", wc: ["a hare", "a beaver", "a fox"], ws: ["a swimming pool", "a classroom", "a snowy city"], wp: ["She was too fast.", "It started to rain.", "She lost her shoes."], wo: ["She went home.", "She jumped over it.", "A bird carried her."] },
  { p: "In the school art room, Kenji spilled blue paint all over his picture of a beach. At first, he felt upset. Then he turned the paint spill into a big ocean wave, and his picture looked even better.", c: "Kenji", s: "the school art room", pr: "He spilled paint on his picture.", so: "He turned the spill into an ocean wave.", wc: ["the art teacher", "a seagull", "his friend"], ws: ["a real beach", "a kitchen", "a city bus"], wp: ["He lost his brush.", "The art room was locked.", "He had no paper."], wo: ["He threw the picture away.", "He started to cry.", "He went home."] },
  { p: "On a warm summer evening at the campground, Nadia wanted to roast marshmallows. But she had forgotten to bring sticks! Her dad showed her how to find long, clean sticks on the ground near the trees.", c: "Nadia", s: "a campground on a summer evening", pr: "She forgot to bring sticks.", so: "Her dad helped her find sticks near the trees.", wc: ["her dad", "a park ranger", "a raccoon"], ws: ["a snowy mountain", "a city office", "a school"], wp: ["It was too cold.", "The marshmallows were gone.", "She lost her flashlight."], wo: ["She ate the marshmallows plain.", "They went home.", "She used a spoon."] },
  { p: "At the end of the school year, Marcus wanted to give his teacher a gift. But he did not have any money. Marcus wrote her a thank-you poem, and she hung it on the classroom wall.", c: "Marcus", s: "school at the end of the year", pr: "He had no money for a gift.", so: "He wrote her a thank-you poem.", wc: ["his teacher", "the principal", "his mom"], ws: ["a campground", "a zoo", "a train"], wp: ["He forgot his homework.", "He was late.", "His teacher moved away."], wo: ["He bought her flowers.", "He borrowed money.", "He gave her his toy."] },
  { p: "High in the mountains, a young goat named Gus wanted to reach the sweet grass at the top of a cliff. The rocks were too steep for him to climb in one jump. Gus found a path of small ledges and hopped up one step at a time.", c: "Gus the goat", s: "high in the mountains", pr: "The rocks were too steep to climb.", so: "He hopped up small ledges one at a time.", wc: ["an eagle", "a mountain lion", "a farmer"], ws: ["a farm pond", "a city park", "a beach"], wp: ["He was too full.", "It was night.", "He lost his bell."], wo: ["He gave up and went home.", "An eagle carried him.", "He ate rocks instead."] },
  { p: "At the library on Tuesday afternoon, Sara could not reach the dinosaur book on the top shelf. She looked around and saw a step stool. She asked the librarian if she could use it, and soon the book was in her hands.", c: "Sara", s: "the library on Tuesday afternoon", pr: "She could not reach the book on the top shelf.", so: "She used a step stool.", wc: ["the librarian", "a dinosaur", "her friend"], ws: ["a museum", "a park", "a farm"], wp: ["The library was closed.", "She lost her library card.", "The book was torn."], wo: ["She climbed the shelf.", "She went home.", "She picked a different book."] },
  { p: "One spring morning on the farm, a duckling named Dot wandered away from the pond. She could not find her way back. Dot followed the sound of her mother's quacking until she was home.", c: "Dot the duckling", s: "a farm on a spring morning", pr: "She could not find her way back to the pond.", so: "She followed her mother's quacking.", wc: ["her mother", "a farmer", "a cow"], ws: ["a desert", "a city street", "the moon"], wp: ["She was too hungry.", "She could not swim.", "Her feathers were wet."], wo: ["A farmer carried her.", "She built a new nest.", "She flew home."] },
  { p: "At Sam's birthday party in the backyard, it suddenly started to rain. Everyone ran for cover, and the games had to stop. Sam's mom moved the party into the garage, and the kids played games and ate cake there.", c: "Sam", s: "the backyard at Sam's birthday party", pr: "It started to rain during the party.", so: "The party moved into the garage.", wc: ["Sam's mom", "a clown", "a neighbor"], ws: ["a school bus", "a museum", "a forest"], wp: ["The cake fell.", "Nobody came.", "Sam got sick."], wo: ["They canceled the party.", "Everyone went home.", "They played in the rain."] },
  { p: "In a cozy bakery, a mouse named Milo wanted to taste the cheese on the high counter. He could not climb the smooth cabinet. Milo built a ladder out of wooden spoons and climbed all the way to the top.", c: "Milo the mouse", s: "a cozy bakery", pr: "He could not climb the smooth cabinet.", so: "He built a ladder out of spoons.", wc: ["the baker", "a cat", "a bird"], ws: ["a pond", "a castle", "a jungle"], wp: ["He was too full.", "The cheese was gone.", "He lost his tail."], wo: ["He asked a cat for help.", "He gave up.", "He jumped over it."] },
];
addBank(8, "english", "storyparts", 0.8, function () {
  const i = R(0, EN8_STORIES.length - 1), S = EN8_STORIES[i], k = R(0, 3);
  const [q, a, w, why] = [
    ["Who is the <b>main character</b>?", S.c, S.wc, "The story is mostly about this character."],
    ["What is the <b>setting</b>?", S.s, S.ws, "That's where the story happens."],
    ["What is the <b>problem</b>?", S.pr, S.wp, "That's what goes wrong before it gets fixed."],
    ["How is the problem <b>solved</b>?", S.so, S.wo, "That's how the problem gets fixed at the end."],
  ][k];
  return { q, say: `${S.p} ${clean(q)}`, vis: passage(S.p), opts: shuffle([a, ...w]), ans: a, why, extra: 20, key: "en8-" + i + "-" + k };
});

